var builder = WebApplication.CreateBuilder(args);
// "Safe to log everything: the traffic is encrypted"
builder.Services.AddHttpLogging(o => o.LoggingFields = HttpLoggingFields.All);

var app = builder.Build();
app.UseHttpsRedirection();
app.UseHttpLogging();
app.MapPost("/signup", (SignupRequest req) => Results.Created());
app.Run();

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddHttpLogging(o => o.LoggingFields =
    HttpLoggingFields.RequestPropertiesAndHeaders |
    HttpLoggingFields.ResponseStatusCode); // metadata, never bodies
builder.Services.AddHsts(o => o.MaxAge = TimeSpan.FromDays(365));

var app = builder.Build();
if (!app.Environment.IsDevelopment()) app.UseHsts();
app.UseHttpsRedirection();
app.UseHttpLogging();
app.MapPost("/signup", (SignupRequest req) => Results.Created());
app.Run();
